package org.eclipse.rdf4j.workbench.security;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.lang.reflect.Constructor;
import java.lang.reflect.Method;
import java.security.SecureRandom;
import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.time.ZoneId;
import java.util.LinkedHashMap;
import java.util.Map;

import javax.crypto.SecretKey;
import javax.crypto.spec.SecretKeySpec;

import org.junit.jupiter.api.Test;

class WorkbenchCredentialCookieCodecSecurityTest {

	@Test
	void encryptsAuthenticatesAndExpiresCredentialCookies() throws Exception {
		MutableClock clock = new MutableClock(Instant.parse("2026-08-21T00:00:00Z"));
		Object codec = codec(Map.of("current", key(1)), "current", clock, Duration.ofDays(30));
		Method encode = codec.getClass()
				.getMethod("encode", String.class, String.class, String.class, String.class,
						String.class);
		Method decode = codec.getClass().getMethod("decode", String.class, String.class, String.class);

		String token = (String) encode.invoke(codec, "server-user-password", "/rdf4j-workbench",
				"https://example.org/rdf4j-server", "alice<script>", "correct horse battery staple");

		assertThat(token).startsWith("v1.current.")
				.doesNotContain("alice")
				.doesNotContain("correct")
				.doesNotContain("example.org");
		Object decoded = decode.invoke(codec, "server-user-password", "/rdf4j-workbench", token);
		assertThat(accessor(decoded, "server")).isEqualTo("https://example.org/rdf4j-server");
		assertThat(accessor(decoded, "username")).isEqualTo("alice<script>");
		assertThat(accessor(decoded, "password")).isEqualTo("correct horse battery staple");
		assertThat(accessor(decoded, "needsRefresh")).isEqualTo(false);

		String tampered = token.substring(0, token.length() - 1) + (token.endsWith("A") ? "B" : "A");
		assertThatThrownBy(() -> decode.invoke(codec, "server-user-password", "/rdf4j-workbench", tampered))
				.hasCauseInstanceOf(SecurityException.class);
		assertThatThrownBy(() -> decode.invoke(codec, "server-user-password", "/other-context", token))
				.hasCauseInstanceOf(SecurityException.class);

		clock.setInstant(clock.instant().plus(Duration.ofDays(31)));
		assertThatThrownBy(() -> decode.invoke(codec, "server-user-password", "/rdf4j-workbench", token))
				.hasCauseInstanceOf(SecurityException.class);
	}

	@Test
	void decryptsRetiredKeysAndRequestsReencryption() throws Exception {
		MutableClock clock = new MutableClock(Instant.parse("2026-08-21T00:00:00Z"));
		Object oldCodec = codec(Map.of("old", key(1)), "old", clock, Duration.ofDays(30));
		Method oldEncode = oldCodec.getClass()
				.getMethod("encode", String.class, String.class, String.class, String.class,
						String.class);
		String token = (String) oldEncode.invoke(oldCodec, "server-user-password", "/workbench",
				"https://example.org/server", "alice", "secret");

		Map<String, SecretKey> rotatedKeys = new LinkedHashMap<>();
		rotatedKeys.put("new", key(2));
		rotatedKeys.put("old", key(1));
		Object rotatedCodec = codec(rotatedKeys, "new", clock, Duration.ofDays(30));
		Method decode = rotatedCodec.getClass().getMethod("decode", String.class, String.class, String.class);
		Object decoded = decode.invoke(rotatedCodec, "server-user-password", "/workbench", token);

		assertThat(accessor(decoded, "username")).isEqualTo("alice");
		assertThat(accessor(decoded, "needsRefresh")).isEqualTo(true);
	}

	private static Object codec(Map<String, SecretKey> keys, String activeKey, Clock clock, Duration lifetime)
			throws Exception {
		Class<?> type = Class.forName("org.eclipse.rdf4j.workbench.security.WorkbenchCredentialCookieCodec");
		Constructor<?> constructor = type.getConstructor(Map.class, String.class, Clock.class, SecureRandom.class,
				Duration.class);
		return constructor.newInstance(keys, activeKey, clock, new SecureRandom(), lifetime);
	}

	private static Object accessor(Object target, String name) throws Exception {
		return target.getClass().getMethod(name).invoke(target);
	}

	private static SecretKey key(int value) {
		byte[] bytes = new byte[32];
		java.util.Arrays.fill(bytes, (byte) value);
		return new SecretKeySpec(bytes, "AES");
	}

	private static final class MutableClock extends Clock {
		private Instant instant;

		private MutableClock(Instant instant) {
			this.instant = instant;
		}

		private void setInstant(Instant instant) {
			this.instant = instant;
		}

		@Override
		public ZoneId getZone() {
			return ZoneId.of("UTC");
		}

		@Override
		public Clock withZone(ZoneId zone) {
			return this;
		}

		@Override
		public Instant instant() {
			return instant;
		}
	}
}
